mapper.select:
SELECT `modality` `name`,COALESCE(count(`id`),0) `num`
FROM `surgical_demonstration`


       and `date_operation` >= #{param.period.begin}


        and `date_operation` <= #{param.period.end}


GROUP BY modality

SELECT COALESCE(count(`id`), 0 ) `num`, DATE_FORMAT(`date_operation`,${dateFormat}) `timeFlag` FROM `surgical_demonstration`
and `date_operation` >= #{st}
and `date_operation` <= #{et}
GROUP BY DATE_FORMAT(`date_operation`, ${dateFormat})

SELECT COALESCE(count(`id`), 0 ) `num`, DATE_FORMAT(`date_operation`,${dateFormat}) `timeFlag` FROM `surgical_demonstration`
and `date_operation` >= #{st}
and `date_operation` <= #{et}
GROUP BY DATE_FORMAT(`date_operation`, ${dateFormat})

SELECT COALESCE(count(`id`), 0 ) `num`, to_char(`date_operation`,${dateFormat}) `timeFlag` FROM `surgical_demonstration`
and `date_operation` >= #{st}
and `date_operation` <= #{et}
GROUP BY DATE_FORMAT(`date_operation`, ${dateFormat})

SELECT `name` `name`,`playback_count` `num`
FROM `surgical_demonstration`


        and `date_operation` >= #{param.period.begin}


        and `date_operation` <= #{param.period.end}


order by `playback_count` DESC
limit 10
